$root=(Get-Location).Path;$web=Join-Path $root 'src/App/Server/GoldEx.Server/wwwroot';$page=Join-Path $web '_viewerqa270.html'
$vendor=(Join-Path $root 'src/App/Server/GoldEx.Server/obj/Release/net10.0/PubTmp/Out/wwwroot/_content/DevExpress.Blazor.Reporting.JSBasedControls.Common/dx-blazor-reporting.css').Replace('\','/')
$base=(Join-Path $web 'css/devexpress-goldex.css').Replace('\','/');$mobile=(Join-Path $web 'css/devexpress-viewer-responsive.css').Replace('\','/')
$html=@"
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="file:///$vendor"><link rel="stylesheet" href="file:///$base"><link rel="stylesheet" href="file:///$mobile"></head><body style="margin:0;--mud-palette-surface:#222226;--mud-palette-background:#151516;--mud-palette-text-primary:#faf7f1;--mud-palette-lines-default:#3c3c3f;--mud-palette-primary:#dfa527">
<div class="gex-report-viewer"><div class="dx-blazor-reporting"><div class="dx-designer-viewport"><div class="dxrd-preview dxrd-designer-wrapper"><div class="dxrd-toolbar-wrapper" id="wrap"><div class="dxrd-toolbar" style="display:flex;align-items:center" id="bar">
<div class="dxrd-toolbar-item" style="flex:none;width:110px">Print</div><div class="dxrd-toolbar-item" style="flex:none;width:110px">Export</div><div class="dxrd-toolbar-item" style="flex:none;width:110px">Search</div><div class="dxrd-toolbar-item" style="flex:none;width:110px">Full</div><div class="dxrd-toolbar-item" style="flex:none;width:110px">Zoom</div><div class="dxrd-toolbar-item" style="flex:none;width:110px"><div class="dx-texteditor"><input id="inp" class="dx-texteditor-input" value="86%"></div></div><div class="dxrd-toolbar-item" style="flex:none;width:110px">Next</div><div class="dxrd-toolbar-item" style="flex:none;width:110px">Prev</div></div></div><div id="side" class="dxd-side-panel-tabs-back-color"></div></div></div></div></div><output id="out"></output>
<script>setTimeout(()=>{let w=document.getElementById('wrap'),b=document.getElementById('bar'),i=document.getElementById('inp');w.scrollLeft=175;let a=w.getBoundingClientRect(),t=b.getBoundingClientRect(),cs=getComputedStyle(w);document.getElementById('out').textContent=JSON.stringify({width:innerWidth,overflow:cs.overflowX,justify:cs.justifyContent,direction:cs.direction,scrollWidth:w.scrollWidth,clientWidth:w.clientWidth,scrollLeft:w.scrollLeft,barLeft:t.left,wrapLeft:a.left,input:getComputedStyle(i).webkitTextFillColor})},100)</script></body></html>
"@
[IO.File]::WriteAllText($page,$html,[Text.UTF8Encoding]::new($false))
try{$url='file:///'+$page.Replace('\','/');$c='C:\Program Files\Google\Chrome\Application\chrome.exe';foreach($width in @(460,1280)){$dom=& $c --headless=new --disable-gpu --disable-extensions --window-size="$width,850" --virtual-time-budget=1500 --dump-dom $url 2>$null |Select-String 'id="out"';if(!$dom -or $dom.Line -notmatch '<output id="out">([^<]+)</output>'){throw 'Fixture unavailable'};$v=[System.Net.WebUtility]::HtmlDecode($Matches[1])|ConvertFrom-Json;Write-Output ('QA_'+$width+'='+($v|ConvertTo-Json -Compress));if($width -eq 460 -and ($v.scrollLeft -le 0 -or $v.overflow -ne 'auto' -or $v.scrollWidth -le $v.clientWidth)){throw 'Mobile toolbar did not scroll'}}}finally{Remove-Item $page -Force -ErrorAction SilentlyContinue}
